  },
  computed: {
    projectOptions() {
      const seen = new Set();
      return this.allItems.filter(i => {
        if (seen.has(i.task_id)) return false;
        seen.add(i.task_id);
        return true;
      }).map(i => ({
        label: i.task_name,
        value: i.task_id,
        so: i.so_number || ''
      })).sort((a, b) => a.label.localeCompare(b.label, 'th'));
    },
    filteredItems() {
      let result = [...this.allItems];
      if (this.filterProject) result = result.filter(i => i.task_id === this.filterProject);
      if (this.filterStatus) result = result.filter(i => i.status === this.filterStatus);
      if (this.searchQuery) {
        const q = this.searchQuery.toLowerCase();
        result = result.filter(i => i.vendor_name?.toLowerCase().includes(q) || i.task_name?.toLowerCase().includes(q) || i.item_description?.toLowerCase().includes(q) || i.po_number?.toLowerCase().includes(q));
      }
      return result;
    },
    filteredProcurementSteps() {
      if (!this.stepSearchQuery) return this.procurementSteps;
      const q = this.stepSearchQuery.toLowerCase();
      return this.procurementSteps.filter(s => s.step_name?.toLowerCase().includes(q) || s.task_name?.toLowerCase().includes(q) || s.so_number?.toLowerCase().includes(q) || s.description?.toLowerCase().includes(q));
    },
    filteredProcurementStepsForImport() {
      return this.procurementSteps.filter(s => (s.id ?? s.step_id) && s.task_id).map(s => ({
        ...s,
        id: s.id ?? s.step_id,
        displayLabel: s.so_number ? `[${s.so_number}] ${s.task_name} — ${s.step_name}` : `${s.task_name} — ${s.step_name}`
      })).sort((a, b) => (a.task_name || '').localeCompare(b.task_name || '', 'th'));
    },
    vendorNoteFiles() {
      if (!this.vendorNoteTarget) return [];
      return this.vendorFiles.filter(f => f.step_id === this.vendorNoteTarget.step_id && f.vendor_name === this.vendorNoteTarget.vendor_name);
    },
    groupedByStep() {
      const groups = {};
      for (const item of this.filteredItems) {
        const key = item.step_id;
        if (!groups[key]) {
          groups[key] = {
            step_id: item.step_id,
            task_id: item.task_id,
            task_name: item.task_name,
            step_name: item.step_name,
            so_number: item.so_number,
            project_manager: item.project_manager,
            items: []
          };
        }
        groups[key].items.push(item);
      }
      return Object.values(groups).sort((a, b) => a.task_name?.localeCompare(b.task_name, 'th'));
    },
    allExpanded() {
      if (!this.groupedByStep.length) return false;
      return this.groupedByStep.every(g => this.expandedGroups[g.step_id]);
    },
    hasActiveFilter() {
      return !!(this.searchQuery || this.filterProject || this.filterStatus);
    },
    todayItems() {
      const today = this.getLocalDateStr(new Date());
      return this.allItems.filter(i => {
        if (!i.delivery_date || i.status === 'completed') return false;
        const dStr = i.delivery_date.split('T')[0];
        return dStr === today;
      });
    },
    overdueItems() {
      const today = this.getLocalDateStr(new Date());
      return this.allItems.filter(i => {
        if (!i.delivery_date || i.status === 'completed' || i.status === 'received') return false;
        const dStr = i.delivery_date.split('T')[0];
        return dStr < today;
      }).sort((a, b) => a.delivery_date.localeCompare(b.delivery_date));
    },
    thisWeekItems() {
      const today = new Date();
      const todayStr = this.getLocalDateStr(today);
      const endOfWeek = new Date(today);
      endOfWeek.setDate(today.getDate() + (7 - today.getDay()));
      const endStr = this.getLocalDateStr(endOfWeek);
      return this.allItems.filter(i => {
        if (!i.delivery_date || i.status === 'completed') return false;
        const dStr = i.delivery_date.split('T')[0];
        return dStr > todayStr && dStr <= endStr;
      }).sort((a, b) => a.delivery_date.localeCompare(b.delivery_date));
    },
    nextWeekItems() {
      const today = new Date();
      const startNext = new Date(today);
      startNext.setDate(today.getDate() + (7 - today.getDay()) + 1);
      const endNext = new Date(startNext);
      endNext.setDate(startNext.getDate() + 6);
      const startStr = this.getLocalDateStr(startNext);
      const endStr = this.getLocalDateStr(endNext);
      return this.allItems.filter(i => {
        if (!i.delivery_date || i.status === 'completed') return false;
        const dStr = i.delivery_date.split('T')[0];
        return dStr >= startStr && dStr <= endStr;
      }).sort((a, b) => a.delivery_date.localeCompare(b.delivery_date));
    },
    upcomingDeliveryItems() {
      const todayStr = this.getLocalDateStr(new Date());
      return this.allItems.filter(i => {
        if (!i.delivery_date || i.status === 'completed' || i.status === 'received') return false;
        const dStr = i.delivery_date.split('T')[0];
        return dStr > todayStr;
      }).sort((a, b) => a.delivery_date.localeCompare(b.delivery_date));
    },
    completedItems() {
      return this.allItems.filter(i => i.status === 'completed' || i.status === 'received');
    },
    allHistoryEvents() {
      const events = [];
      for (const item of this.allItems) {
        // ข้อมูลร่วมของทุก event เพื่อให้ไทม์ไลน์แสดงรายละเอียดครบ
        const common = {
          vendor_name: item.vendor_name,
          task_name: item.task_name,
          so_number: item.so_number,
          step_name: item.step_name,
          item_description: item.item_description,
          po_number: item.po_number,
          amount: item.amount
        };
        // Event: เพิ่ม vendor
        if (item.created_at) {
          events.push({
            ...common,
            key: `created-${item.id}`,
            type: 'created',
            description: `เพิ่มรายการจัดซื้อ`,
            remark: '',
            changed_by: item.created_by_name || '',
            date: item.created_at.split('T')[0],
            datetime: item.created_at,
            time: this.formatDateTime(item.created_at),
            badge: 'เพิ่มใหม่',
            to: 'pending',
            dotColor: 'approved'
          });
        }
        // Events: ประวัติเปลี่ยนสถานะ
        if (item.status_history && item.status_history.length > 0) {
          for (const h of item.status_history) {
            events.push({
              ...common,
              key: `hist-${item.id}-${h.changed_at}`,
              type: 'status_change',
              description: `${this.getItemStatusLabel(h.from)} → ${this.getItemStatusLabel(h.to)}`,
              remark: h.remark || '',
              changed_by: h.changed_by || '',
              date: h.changed_at ? h.changed_at.split('T')[0] : '',
              datetime: h.changed_at,
              time: this.formatDateTime(h.changed_at),
              badge: this.getItemStatusLabel(h.to),
              from: h.from,
              to: h.to,
              dotColor: h.to
            });
          }
        }
        // Event: กำหนดส่ง (upcoming) - เฉพาะที่ยังไม่เสร็จ
        if (item.delivery_date && item.status !== 'completed' && item.status !== 'received') {
          const dStr = item.delivery_date.split('T')[0];
          events.push({
            ...common,
            key: `delivery-${item.id}`,
            type: 'delivery',
            description: `กำหนดส่ง`,
            remark: '',
            changed_by: '',
            date: dStr,
            datetime: item.delivery_date,
            time: this.formatDate(item.delivery_date),
            badge: 'กำหนดส่ง',
            to: item.status,
            dotColor: 'delivery'
          });
        }
      }
      return events.sort((a, b) => (b.datetime || '').localeCompare(a.datetime || ''));
    },
    todayHistoryEvents() {
      const today = this.getLocalDateStr(new Date());
      return this.allHistoryEvents.filter(e => e.date === today && e.type !== 'delivery');
    },
    selectedDateEvents() {
      if (!this.calendarDate) return [];
      const selStr = this.getLocalDateStr(this.calendarDate);
      return this.allHistoryEvents.filter(e => e.date === selStr);
    },
    // รายการจัดซื้อที่มีกำหนดส่งในวันที่เลือกในปฏิทิน
    selectedDateDeliveryItems() {
      if (!this.calendarDate) return [];
      const selStr = this.getLocalDateStr(this.calendarDate);
      return this.allItems.filter(i => i.delivery_date && i.delivery_date.split('T')[0] === selStr);
    }
  },
  mounted() {
    this.loadData();
    this.setupVendorListDragScroll();
  },
  beforeUnmount() {
    // เก็บกวาด event listeners ของ drag-scroll ตารางหลัก
    if (this._vendorDragHandlers) {
      document.removeEventListener('mousedown', this._vendorDragHandlers.down);
      document.removeEventListener('mousemove', this._vendorDragHandlers.move);
      document.removeEventListener('mouseup', this._vendorDragHandlers.up);
    }
  },
  methods: {
    // กดค้างที่พื้นที่ว่างในตารางหลัก แล้วลากเพื่อเลื่อนซ้าย-ขวา (ไม่ต้องใช้ scrollbar)
    // แต่ถ้ากดบนข้อความ → ให้เลือก/highlight ข้อความได้ตามปกติ
    setupVendorListDragScroll() {
      let isDown = false;
      let startX = 0;
      let startScroll = 0;

      // เช็คว่า element ที่กดมีข้อความตรง ๆ อยู่ไหม (มี = ให้เลือกข้อความ ไม่ drag)
      const hasDirectText = el => {
        return Array.from(el.childNodes).some(n => n.nodeType === Node.TEXT_NODE && n.textContent.trim().length > 0);
      };
      const down = e => {
        const target = e.target.closest('.vendor-list');
        if (!target) return;
        // ไม่รบกวนการคลิก/พิมพ์ใน input, ปุ่ม, dropdown
        if (e.target.closest('input, textarea, button, a, .p-dropdown, .p-button, .p-checkbox')) return;
        // กดบนข้อความ → ให้ highlight/เลือกข้อความได้ (ไม่เริ่ม drag)
        if ((e.target.tagName === 'SPAN' || e.target.tagName === 'DIV' || e.target.tagName === 'TD' || e.target.tagName === 'STRONG' || e.target.tagName === 'H5') && hasDirectText(e.target)) return;
        isDown = true;
        startX = e.pageX;
        startScroll = target.scrollLeft;
        target.style.cursor = 'grabbing';
      };
      const move = e => {
        if (!isDown) return;
        const target = e.target.closest('.vendor-list');
        if (!target) return;
        const dx = e.pageX - startX;
        // เริ่ม drag จริงเมื่อลากเกิน 5px แล้วค่อยกันการเลือกข้อความ
        if (Math.abs(dx) > 5) {
          target.style.userSelect = 'none';
          e.preventDefault();
        }
        target.scrollLeft = startScroll - dx;
      };
      const up = () => {
        if (!isDown) return;
        isDown = false;
        document.querySelectorAll('.vendor-list').forEach(el => {
          el.style.cursor = 'grab';
          el.style.userSelect = '';
        });
      };
      document.addEventListener('mousedown', down);
      document.addEventListener('mousemove', move);
      document.addEventListener('mouseup', up);
      this._vendorDragHandlers = {
        down,
        move,
        up
      };
    },
    async loadData() {
      try {
        const [stepsRes, itemsRes, usersRes, vendorsRes, vendorNotesRes, vendorFilesRes] = await Promise.all([axios.get('/api/task-steps/procurement'), axios.get('/api/procurement'), axios.get('/api/users'), axios.get('/api/procurement/vendors'), axios.get('/api/procurement/vendor-notes', {
          silent: true
        }).catch(() => ({
          data: []
        })), axios.get('/api/procurement/vendor-files', {
          silent: true
        }).catch(() => ({
          data: []
        }))]);
        this.procurementSteps = stepsRes.data;
        this.allItems = itemsRes.data;
        this.vendorNotes = vendorNotesRes.data || [];
        this.vendorFiles = vendorFilesRes.data || [];
        this.users = usersRes.data.map(u => ({
          id: u.id,
          name: `${u.firstname} ${u.lastname}${u.nickname ? ` (${u.nickname})` : ''}`
        }));
        this.vendorList = vendorsRes.data || [];
        // Auto expand all groups on first load
        if (Object.keys(this.expandedGroups).length === 0) {
          for (const g of this.groupedByStep) {
            this.expandedGroups[g.step_id] = true;
          }
        }
      } catch (e) {
        console.error(e);
      } finally {
        this.loading = false;
      }
    },
    toggleGroup(stepId) {
      this.expandedGroups[stepId] = !this.expandedGroups[stepId];
    },
    // จัดกลุ่ม item ในโครงการเดียวกันตามชื่อ vendor (ชื่อซ้ำ = รวมเป็น cluster เดียว)
    getVendorClusters(group) {
      const map = {},
        order = [];
      for (const item of group.items) {
        const name = item.vendor_name || '(ไม่ระบุชื่อ)';
        if (!map[name]) {
          map[name] = {
            vendor_name: name,
            items: []
          };
          order.push(map[name]);
        }
        map[name].items.push(item);
      }
      return order.map(c => ({
        ...c,
        repeated: c.items.length > 1
      }));
    },
    vendorKey(group, cluster) {
      return group.step_id + '::' + cluster.vendor_name;
    },
    isVendorExpanded(key) {
      return !!this.expandedVendors[key];
    },
    toggleVendorGroup(key) {
      this.expandedVendors[key] = !this.expandedVendors[key];
    },
    // สรุปสถานะของ vendor cluster: นับจำนวนแยกตามสถานะ (แสดงเป็น 2 คอลัมน์ย่อย)
    getClusterStatusCounts(items) {
      const counts = {};
      for (const i of items) counts[i.status] = (counts[i.status] || 0) + 1;
      // เรียงตามลำดับ flow เพื่อให้ chip เรียงจากต้นไปจนถึงปลาย
      const flow = ['pending', 'negotiating', 'approved', 'ordered', 'awaiting_payment', 'waiting', 'ready_to_ship', 'received', 'completed'];
      return flow.filter(st => counts[st]).map(st => ({
        status: st,
        count: counts[st]
      }));
    },
    // บรรทัดรายละเอียดของ item สำหรับไทม์ไลน์: รายละเอียดสินค้า + PO + ผู้รับผิดชอบ
    getItemDetailLine(item) {
      const parts = [];
      if (item.item_description) parts.push(item.item_description);
      if (item.po_number) parts.push('PO: ' + item.po_number);
      if (item.assigned_user_name) parts.push('ผู้รับผิดชอบ: ' + item.assigned_user_name);
      return parts.join(' • ');
    },
    // จัดรูปยอดเงินเป็นทศนิยม 2 ตำแหน่ง เช่น 100,000.00 (คืน null ถ้าไม่มี/ไม่ใช่ตัวเลข)
    // Mark/unmark รายการ: ส่งอีเมลแจ้ง PM เมื่อสถานะเปลี่ยน
    async toggleNotifyPm(item) {
      try {
        const res = await axios.put(`/api/procurement/${item.id}/notify`);
        item.notify_pm = res.data.notify_pm;
        this.$toast.add({
          severity: res.data.notify_pm ? 'success' : 'info',
          summary: res.data.notify_pm ? 'เปิดแจ้งเตือน PM' : 'ปิดแจ้งเตือน PM',
          detail: res.data.notify_pm ? 'จะส่งอีเมลแจ้ง PM ทุกครั้งที่สถานะของรายการนี้เปลี่ยน' : 'รายการนี้จะไม่ส่งอีเมลแจ้ง PM',
          life: 2500
        });
      } catch (e) {
        this.$toast.add({
          severity: 'error',
          summary: 'ผิดพลาด',
          detail: 'ไม่สามารถตั้งค่าการแจ้งเตือนได้',
          life: 3000
        });
      }
    },
    formatMoney(v) {
      if (v === null || v === undefined || v === '') return null;
      const n = Number(v);
      if (isNaN(n)) return null;
      return n.toLocaleString('th-TH', {
        minimumFractionDigits: 0,
        maximumFractionDigits: 2
      });
    },
    // ผลรวมยอดเงินของรายการชุดหนึ่ง (คืน null ถ้าไม่มีรายการใดมียอดเงินเลย)
    sumAmount(items) {
      let sum = 0,
        has = false;
      for (const i of items) {
        if (i.amount === null || i.amount === undefined || i.amount === '') continue;
        const n = Number(i.amount);
        if (!isNaN(n)) {
          sum += n;
          has = true;
        }
      }
      return has ? Math.round(sum * 100) / 100 : null;
    },
    // ดึง leadtime จากหมายเหตุ เช่น "** leadtime 20 วัน" → "20 วัน"
    getLeadtimeFromNotes(notes) {
      if (!notes) return null;
      const m = String(notes).match(/leadtime\s*:?\s*(\d+(?:\s*-\s*\d+)?)\s*วัน/i);
      return m ? m[1].replace(/\s+/g, '') + ' วัน' : null;
    },
    // leadtime ที่ไม่ซ้ำกันของ vendor cluster (สำหรับแถวรวม)
    getClusterLeadtimes(items) {
      const seen = new Set();
      for (const i of items) {
        const lt = this.getLeadtimeFromNotes(i.notes);
        if (lt) seen.add(lt);
      }
      return [...seen].join(', ') || null;
    },
    // หมายเหตุระดับ vendor ของ step นี้ (ใช้ร่วมทุกรายการของ vendor)
    getVendorNote(group, cluster) {
      if (!group || !cluster) return null;
      const note = this.vendorNotes.find(n => n.step_id === group.step_id && n.vendor_name === cluster.vendor_name);
      // คืน null ถ้าไม่มี note หรือ comment ว่าง
      if (!note || !note.comment || note.comment.trim() === '') return null;
      return note;
    },
    // ตัดช่องว่าง/บรรทัดเกินหน้า-หลัง กันข้อความเว้นวรรคช่องแรก (รวม NBSP/Zero-width space ที่มาจาก Excel)
    trimNote(text) {
      return text ? String(text).replace(/\u200B/g, '').replace(/\u200C/g, '').replace(/\u200D/g, '').replace(/\uFEFF/g, '').replace(/\u00A0/g, ' ').replace(/\s+/g, ' ').trim() : '';
    },
    openVendorNoteDialog(group, cluster) {
      this.vendorNoteTarget = {
        step_id: group.step_id,
        task_id: group.task_id,
        vendor_name: cluster.vendor_name,
        is_repeated: cluster.repeated,
        item_count: cluster.items?.length || 1
      };
      const existing = this.getVendorNote(group, cluster);
      this.vendorNoteText = existing ? this.trimNote(existing.comment) : '';
      this.pendingVendorFiles = [];
      this.pendingDeleteFileIds = [];
      this.showVendorNoteDialog = true;
    },
    cancelVendorNote() {
      // Restore files that were marked for deletion
      if (this.pendingDeleteFileIds.length > 0) {
        this.reloadVendorFilesOnly();
      }
      this.pendingVendorFiles = [];
      this.pendingDeleteFileIds = [];
      this.showVendorNoteDialog = false;
    },
    triggerVendorFileUpload() {
      this.$refs.vendorFileInput && this.$refs.vendorFileInput.click();
    },
    onVendorFileSelect(e) {
      const files = Array.from(e.target.files || []);
      e.target.value = '';
      for (const f of files) {
        if (f.size > 200 * 1024 * 1024) {
          this.$toast.add({
            severity: 'warn',
            summary: `ไฟล์ "${f.name}" ใหญ่เกินไป`,
            detail: 'ขนาดไฟล์ต้องไม่เกิน 200MB',
            life: 3000
          });
          continue;
        }
        this.pendingVendorFiles.push(f);
      }
    },
    async saveVendorNote() {
      if (!this.vendorNoteTarget) return;
      this.vendorNoteUploading = true;
      try {
        // 1. บันทึก note
        await axios.put('/api/procurement/vendor-notes', {
          step_id: this.vendorNoteTarget.step_id,
          vendor_name: this.vendorNoteTarget.vendor_name,
          comment: (this.vendorNoteText || "").trim()
        });
        // 2. upload ไฟล์ที่รอ
        for (const file of this.pendingVendorFiles) {
          const fd = new FormData();
          fd.append('file', file);
          fd.append('step_id', this.vendorNoteTarget.step_id);
          fd.append('vendor_name', this.vendorNoteTarget.vendor_name);
          await axios.post('/api/procurement/vendor-files', fd);
        }
        // 3. ลบไฟล์ที่รอลบ (จาก pendingDeleteFileIds)
        for (const fileId of this.pendingDeleteFileIds) {
          await axios.delete(`/api/procurement/vendor-files/${fileId}`);
        }
        this.pendingVendorFiles = [];
        this.pendingDeleteFileIds = [];
        this.$toast.add({
          severity: 'success',
          summary: 'บันทึกเรียบร้อย',
          life: 2000
        });
        this.showVendorNoteDialog = false;
        await this.reloadVendorFilesOnly();
      } catch (e) {
        this.$toast.add({
          severity: 'error',
          summary: 'ผิดพลาด',
          detail: e.response?.data?.error || 'บันทึกไม่สำเร็จ',
          life: 3000
        });
      } finally {
        this.vendorNoteUploading = false;
      }
    },
    async reloadVendorFilesOnly() {
      try {
        const [filesRes, notesRes, itemsRes] = await Promise.all([axios.get('/api/procurement/vendor-files', {
          silent: true
        }).catch(() => ({
          data: []
        })), axios.get('/api/procurement/vendor-notes', {
          silent: true
        }).catch(() => ({
          data: []
        })), axios.get('/api/procurement', {
          silent: true
        })]);
        this.vendorFiles = filesRes.data || [];
        this.vendorNotes = notesRes.data || [];
        this.allItems = itemsRes.data;
      } catch (e) {
        console.error(e);
      }
    },
    getVendorFiles(group, cluster) {
      if (!group || !cluster) return [];
      return this.vendorFiles.filter(f => f.step_id === group.step_id && f.vendor_name === cluster.vendor_name);
    },
    deleteVendorFile(f) {
      this.$confirm.require({
        message: `ลบไฟล์ "${f.file_name}"?`,
        header: 'ยืนยันการลบ',
        icon: 'pi pi-exclamation-triangle',
        acceptLabel: 'ลบ',
        rejectLabel: 'ยกเลิก',
        acceptClass: 'p-button-danger',
        accept: () => {
          // Add to pending delete list instead of deleting immediately
          if (!this.pendingDeleteFileIds.includes(f.id)) {
            this.pendingDeleteFileIds.push(f.id);
          }
          // Remove from local display immediately
          this.vendorFiles = this.vendorFiles.filter(file => file.id !== f.id);
          this.$toast.add({
            severity: 'success',
            summary: 'เพิ่มลงรายการลบ',
            detail: 'ไฟล์จะถูกลบเมื่อกดบันทึก',
            life: 2000
          });
        }
      });
    },
    formatFileSize(bytes) {
      if (!bytes && bytes !== 0) return '';
      if (bytes < 1024) return bytes + ' B';
      if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
      return (bytes / 1024 / 1024).toFixed(2) + ' MB';
    },
    toggleAllGroups() {
      const target = !this.allExpanded;
      for (const g of this.groupedByStep) {
        this.expandedGroups[g.step_id] = target;
      }
    },
    clearFilters() {
      this.searchQuery = '';
      this.filterProject = null;
      this.filterStatus = null;
    },
    getGroupProgress(group) {
      if (!group.items.length) return 0;
      const total = group.items.reduce((sum, i) => sum + this.getProgressPercent(i.status), 0);
      return Math.round(total / group.items.length);
    },
    getGroupOverdue(group) {
      return group.items.filter(i => this.isOverdue(i)).length;
    },
    countByStatus(status) {
      return this.allItems.filter(i => i.status === status).length;
    },
    getProjectLabel(taskId) {
      const opt = this.projectOptions.find(p => p.value === taskId);
      if (!opt) return '';
      return opt.so ? `[${opt.so}] ${opt.label}` : opt.label;
    },
    hasDeliveryOnDate(dateObj) {
      const d = `${dateObj.year}-${String(dateObj.month + 1).padStart(2, '0')}-${String(dateObj.day).padStart(2, '0')}`;
      return this.allItems.some(i => i.delivery_date && i.delivery_date.split('T')[0] === d && i.status !== 'completed' && i.status !== 'received');
    },
    isOverdue(item) {
      if (!item.delivery_date || item.status === 'completed' || item.status === 'received') return false;
      const todayStr = this.getLocalDateStr(new Date());
      const dStr = item.delivery_date.split('T')[0];
      return dStr < todayStr;
    },
    onDateSelect() {
      // Calendar date selected - selectedDateItems computed จะ update อัตโนมัติ
    },
    getLocalDateStr(date) {
      const d = new Date(date);
      return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    },
    getProgressPercent(status) {
      const map = {
        pending: 0,
        negotiating: 10,
        approved: 20,
        ordered: 35,
        awaiting_payment: 50,
        waiting: 60,
        ready_to_ship: 75,
        received: 85,
        completed: 100
      };
      return map[status] || 0;
    },
    getItemStatusLabel(status) {
      const found = this.itemStatusOptions.find(s => s.value === status);
      return found ? found.label : status;
    },
    getNextStatus(status) {
      const flow = ['pending', 'negotiating', 'approved', 'ordered', 'awaiting_payment', 'waiting', 'ready_to_ship', 'received', 'completed'];
      const idx = flow.indexOf(status);
      return idx >= 0 && idx < flow.length - 1 ? flow[idx + 1] : null;
    },
    getNextActionLabel(status) {
      const map = {
        pending: 'ต่อรอง',
        negotiating: 'อนุมัติ',
        approved: 'สั่งซื้อ',
        ordered: 'รอชำระเงิน',
        awaiting_payment: 'รอของ',
        waiting: 'ของพร้อมส่ง',
        ready_to_ship: 'ของมาแล้ว',
        received: 'เสร็จสิ้น'
      };
      return map[status] || '';
    },
    // เลือกสถานะใหม่จาก dropdown ในตาราง → เปิด dialog ใส่หมายเหตุ
    pickStatus(item, newStatus) {
      if (!newStatus || newStatus === item.status) return;
      this.requestStatusChange(item, newStatus);
    },
    requestStatusChange(item, toStatus) {
      if (!toStatus || toStatus === item.status) return;
      this.remarkItem = item;
      this.remarkFromStatus = item.status;
      this.remarkToStatus = toStatus;
      this.remarkText = '';
      this.showRemarkDialog = true;
    },
    async advanceStatus(item) {
      const next = this.getNextStatus(item.status);
      if (!next) return;
      this.remarkItem = item;
      this.remarkFromStatus = item.status;
      this.remarkToStatus = next;
      this.remarkText = '';
      this.showRemarkDialog = true;
    },
    cancelStatusChange() {
      this.showRemarkDialog = false;
      this.remarkItem = null;
    },
    async confirmStatusChange() {
      if (!this.remarkItem) return;
      try {
        await axios.put(`/api/procurement/${this.remarkItem.id}`, {
          status: this.remarkToStatus,
          status_remark: this.remarkText
        });
        this.showRemarkDialog = false;
        await this.loadData();
        this.$toast.add({
          severity: 'success',
          summary: 'สำเร็จ',
          detail: `เปลี่ยนสถานะเป็น "${this.getItemStatusLabel(this.remarkToStatus)}"`,
          life: 3000
        });
      } catch (e) {
        console.error(e);
        this.$toast.add({
          severity: 'error',
          summary: 'ผิดพลาด',
          detail: 'ไม่สามารถเปลี่ยนสถานะได้',
          life: 3000
        });
      }
    },
    openHistory(item) {
      this.historyItem = item;
      this.showHistoryDialog = true;
    },
    formatDateTime(dt) {
      if (!dt) return '';
      const d = new Date(dt);
      return d.toLocaleDateString('th-TH', {
        day: 'numeric',
        month: 'short',
        year: '2-digit'
      }) + ' ' + d.toLocaleTimeString('th-TH', {
        hour: '2-digit',
        minute: '2-digit'
      });
    },
    getHistoryDotColor(evt) {
      if (evt.type === 'created') return 'new';
      if (evt.to === 'completed') return 'completed';
      return evt.to || 'pending';
    },
    getHistoryEventClass(evt) {
      if (evt.type === 'created') return 'cal-event-created';
      if (evt.to === 'completed') return 'cal-event-completed';
      return 'cal-event-history';
    },
    getHistoryBadgeClass(evt) {
      if (evt.type === 'created') return 'badge-new';
      if (evt.to === 'completed') return 'badge-completed';
      return 'badge-' + evt.to;
    },
    openAddItem(step) {
      // รองรับทั้ง step object จาก procurementSteps (มี id) และ group object จาก groupedByStep (มี step_id)
      this.currentStep = {
        id: step.id || step.step_id,
        task_id: step.task_id
      };
      this.editingItem = null;
      this.showSelectStepDialog = false;
      this.currentItem = {
        vendor_name: '',
        item_description: '',
        po_number: '',
        order_date: null,
        delivery_date: null,
        status: 'pending',
        notes: '',
        leadtime: '',
        assigned_user_id: null,
        assigned_user_name: ''
      };
      this.showItemDialog = true;
    },
    openEditItem(item) {
      this.currentStep = {
        id: item.step_id,
        task_id: item.task_id
      };
      this.editingItem = item;
      this.currentItem = {
        ...item,
        order_date: item.order_date ? new Date(item.order_date) : null,
        delivery_date: item.delivery_date ? new Date(item.delivery_date) : null
      };
      // แยก leadtime จาก notes ให้แสดงในฟิลด์ของตัวเอง
      const ltMatch = item.notes ? String(item.notes).match(/leadtime\s*:?\s*(\d+(?:\s*-\s*\d+)?)\s*วัน/i) : null;
      this.currentItem.leadtime = ltMatch ? ltMatch[1].replace(/\s+/g, '') : '';
      this.currentItem.notes = item.notes ? String(item.notes).replace(/\s*\*{0,2}\s*leadtime\s*:?\s*\d+(?:\s*-\s*\d+)?\s*วัน\s*/i, ' ').replace(/\s{2,}/g, ' ').trim() : '';
      this.showItemDialog = true;
    },
    onAssignedUserChange() {
      const user = this.users.find(u => u.id === this.currentItem.assigned_user_id);
      this.currentItem.assigned_user_name = user ? user.name : '';
    },
    searchVendor(event) {
      const q = event.query.toLowerCase();
      this.vendorSuggestions = q ? this.vendorList.filter(v => v.toLowerCase().includes(q)) : [...this.vendorList];
    },
    getVendorNameStr(v) {
      if (!v) return '';
      if (typeof v === 'string') return v.trim();
      if (typeof v === 'object') return (v.value || v.name || '').trim();
      return '';
    },
    async onImportFileChange(e) {
      const file = e.target.files && e.target.files[0];
      e.target.value = ''; // reset เพื่อให้เลือกไฟล์เดิมซ้ำได้
      if (!file) return;
      if (!/\.(xlsx|xls)$/i.test(file.name)) {
        this.$toast.add({
          severity: 'warn',
          summary: 'ไฟล์ไม่ถูกต้อง',
          detail: 'รองรับเฉพาะไฟล์ .xlsx / .xls',
          life: 3000
        });
        return;
      }
      if (file.size > 200 * 1024 * 1024) {
        this.$toast.add({
          severity: 'warn',
          summary: 'ไฟล์ใหญ่เกินไป',
          detail: 'ขนาดไฟล์ต้องไม่เกิน 200MB',
          life: 3000
        });
        return;
      }
      this.importLoading = true;
      try {
        const fd = new FormData();
        fd.append('file', file);
        const res = await axios.post('/api/procurement/import/preview', fd);
        this.importFormat = res.data.format || 'BOQ';
        this.importPreview = (res.data.vendors || []).map(v => ({
          ...v,
          status: v.status || 'pending'
        }));
        this.importWarnings = res.data.warnings || [];
        this.showImportDialog = true;
        if (this.importPreview.length === 0) {
          this.$toast.add({
            severity: 'info',
            summary: 'ไม่พบข้อมูล',
            detail: 'ไม่พบรายการ vendor ในไฟล์นี้ — ตรวจสอบว่ากรอกข้อมูลครบ (Distributor/รายละเอียด หรือชื่อ tab vendor)',
            life: 5000
          });
        }
      } catch (err) {
        console.error(err);
        this.$toast.add({
          severity: 'error',
          summary: 'อ่านไฟล์ไม่สำเร็จ',
          detail: err.response?.data?.error || err.userMessage || 'ไม่สามารถอ่านไฟล์ Excel ได้',
          life: 4000
        });
      } finally {
        this.importLoading = false;
      }
    },
    async confirmImport() {
      if (!this.importTargetStep) return;
      const vendors = this.importPreview.filter(v => v.vendor_name && String(v.vendor_name).trim());
      if (vendors.length === 0) return;
      this.importLoading = true;
      try {
        const payload = {
          step_id: this.importTargetStep.id,
          task_id: this.importTargetStep.task_id,
          vendors: vendors.map(v => {
            const clean = {
              ...v
            };
            delete clean._sheet; // ตัด field ชั่วคราวจาก parser ออกก่อนส่ง
            delete clean._skip;
            delete clean.leadtime; // leadtime ไม่มีคอลัมน์ใน DB (อยู่ใน notes แล้ว)
            return clean;
          })
        };
        const res = await axios.post('/api/procurement/import/confirm', payload);
        this.showImportDialog = false;
        this.importPreview = [];
        this.importWarnings = [];
        this.importTargetStep = null;
        this.$toast.add({
          severity: 'success',
          summary: 'นำเข้าสำเร็จ',
          detail: `เพิ่ม ${res.data.created} รายการเรียบร้อย`,
          life: 3000
        });
        await this.loadData();
      } catch (err) {
        console.error(err);
        this.$toast.add({
          severity: 'error',
          summary: 'นำเข้าไม่สำเร็จ',
          detail: err.response?.data?.error || err.userMessage || 'ไม่สามารถนำเข้าข้อมูลได้',
          life: 4000
        });
      } finally {
        this.importLoading = false;
      }
    },
    async saveItem() {
      // vendor_name อาจเป็น string หรือ object จาก AutoComplete
      const vendorName = typeof this.currentItem.vendor_name === 'object' ? this.currentItem.vendor_name?.value || this.currentItem.vendor_name?.name || '' : this.currentItem.vendor_name || '';
      if (!vendorName.trim()) {
        this.$toast.add({
          severity: 'warn',
          summary: 'กรุณากรอกชื่อ Vendor',
          life: 3000
        });
        return;
      }
      let notesVal = String(this.currentItem.notes || '').replace(/\s*\*{0,2}\s*leadtime\s*:?\s*\d+(?:\s*-\s*\d+)?\s*วัน\s*/i, ' ').replace(/\s{2,}/g, ' ').trim();
      const ltVal = String(this.currentItem.leadtime || '').trim();
      if (ltVal) notesVal = (notesVal ? notesVal + ' ' : '') + '** leadtime ' + ltVal + ' วัน';
      const data = {
        ...this.currentItem,
        vendor_name: vendorName.trim(),
        step_id: this.currentStep.id,
        task_id: this.currentStep.task_id,
        order_date: this.currentItem.order_date ? this.fmtDate(this.currentItem.order_date) : null,
        delivery_date: this.currentItem.delivery_date ? this.fmtDate(this.currentItem.delivery_date) : null
      };
      data.notes = notesVal;
      delete data.leadtime;
      try {
        if (this.editingItem) {
          await axios.put(`/api/procurement/${this.editingItem.id}`, data);
        } else {
          await axios.post('/api/procurement', data);
        }
        this.showItemDialog = false;
        this.$toast.add({
          severity: 'success',
          summary: 'สำเร็จ',
          detail: 'บันทึกเรียบร้อย',
          life: 3000
        });
        await this.loadData();
      } catch (e) {
        this.$toast.add({
          severity: 'error',
          summary: 'ผิดพลาด',
          detail: e.response?.data?.error || 'ไม่สามารถบันทึกได้',
          life: 3000
        });
      }
    },
    deleteItem(item) {
      this.$confirm.require({
        message: `ลบ "${item.vendor_name}"?`,
        header: 'ยืนยันการลบ',
        icon: 'pi pi-exclamation-triangle',
        acceptLabel: 'ลบ',
        rejectLabel: 'ยกเลิก',
        acceptIcon: 'pi pi-trash',
        rejectIcon: 'pi pi-times',
        acceptClass: 'p-button-danger',
        accept: async () => {
          await axios.delete(`/api/procurement/${item.id}`);
          await this.loadData();
          this.$toast.add({
            severity: 'success',
            summary: 'ลบแล้ว',
            life: 2000
          });
        }
      });
    },
    goToProject(item) {
      this.$router.push({
        path: '/project-progress',
        query: {
          taskId: item.task_id,
          stepId: item.step_id
        }
      });
    },
    formatDate(d) {
      if (!d) return '';
      // ใช้ split เพื่อหลีกเลี่ยง timezone issue
      const parts = d.split('T')[0].split('-');
      const date = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]));
      return date.toLocaleDateString('th-TH', {
        day: 'numeric',
        month: 'short',
        year: '2-digit'
      });
    },
    formatFullDate(d) {
      const date = new Date(d);
      return date.toLocaleDateString('th-TH', {
        day: 'numeric',
        month: 'long',
        year: 'numeric'
      });
    },
    getDeliveryLabel(item) {
      if (!item.delivery_date) return '';
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const del = new Date(item.delivery_date);
      del.setHours(0, 0, 0, 0);
      const diff = Math.ceil((del - today) / (1000 * 60 * 60 * 24));
      if (diff === 0) return 'วันนี้';
      if (diff === 1) return 'พรุ่งนี้';
      if (diff < 0) return 'เลยกำหนด';
      return `อีก ${diff} วัน`;
    },
    getOverdueDays(item) {
      if (!item.delivery_date) return 0;
      const todayStr = this.getLocalDateStr(new Date());
      const dStr = item.delivery_date.split('T')[0];
      const today = new Date(todayStr + 'T00:00:00');
      const del = new Date(dStr + 'T00:00:00');
      return Math.abs(Math.floor((today - del) / (1000 * 60 * 60 * 24)));
    },
    fmtDate(d) {
      const x = new Date(d);
      return `${x.getFullYear()}-${String(x.getMonth() + 1).padStart(2, '0')}-${String(x.getDate()).padStart(2, '0')}`;
    }
  }
};
